vec3 ACESToneMap (vec3 color) {
  color = min(color, vec3(8.0));
  const float A = 2.51;
  const float B = 0.03;
  const float C = 2.43;
  const float D = 0.59;
  const float E = 0.14;
  return (color * (A * color + B)) / (color * (C * color + D) + E);
}
vec3 LinearToSRGB(vec3 linear) {
#ifdef CC_USE_SURFACE_SHADER
  #if CC_USE_DEBUG_VIEW == CC_SURFACES_DEBUG_VIEW_COMPOSITE_AND_MISC && CC_SURFACES_ENABLE_DEBUG_VIEW
    if (!IS_DEBUG_VIEW_COMPOSITE_ENABLE_GAMMA_CORRECTION) {
      return linear;
    }
  #endif
#endif
  return sqrt(linear);
}
vec4 packRGBE (vec3 rgb) {
  highp float maxComp = max(max(rgb.r, rgb.g), rgb.b);
  highp float e = 128.0;
  if (maxComp > 0.0001) {
    e = log(maxComp) / log(1.1);
    e = ceil(e);
    e = clamp(e + 128.0, 0.0, 255.0);
  }
  highp float sc = 1.0 / pow(1.1, e - 128.0);
  vec3 encode = clamp(rgb * sc, vec3(0.0), vec3(1.0)) * 255.0;
  vec3 encode_rounded = floor(encode) + step(encode - floor(encode), vec3(0.5));
  return vec4(encode_rounded, e) / 255.0;
}
vec4 CCFragOutput (vec4 color) {
  #if CC_USE_RGBE_OUTPUT
    color = packRGBE(color.rgb);
  #elif !CC_USE_FLOAT_OUTPUT
    #if CC_USE_HDR && CC_TONE_MAPPING_TYPE == HDR_TONE_MAPPING_ACES
      color.rgb = ACESToneMap(color.rgb);
    #endif
    color.rgb = LinearToSRGB(color.rgb);
  #endif
  return color;
}
layout(std140) uniform Constants {
  vec4 auraColor;
  vec4 auraParams;
};
in vec2 v_uv;
vec4 frag () {
  float dist = length(v_uv - vec2(0.5)) * 2.0;
  if (dist > 1.0) {
    discard;
  }
  float rimWidth = auraParams.y;
  float pulseSpeed = auraParams.x;
  float rim = smoothstep(1.0 - rimWidth, 0.98, dist) * (1.0 - smoothstep(0.98, 1.0, dist));
  float innerFill = (1.0 - dist) * 0.35;
  float pulse = sin(cc_time.x * pulseSpeed) * 0.15 + 0.85;
  float alpha = (rim * 2.0 + innerFill) * pulse * auraColor.a;
  vec3 rgb = auraColor.rgb + vec3(rim * 0.6);
  return CCFragOutput(vec4(rgb, clamp(alpha, 0.0, 1.0)));
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

